CREATE TYPE "ScoreFormat" AS ENUM ('GUITAR_PRO', 'MUSIC_XML', 'ALPHA_TEX');
CREATE TABLE "ExerciseScore" ("id" TEXT NOT NULL, "exerciseId" TEXT NOT NULL, "format" "ScoreFormat" NOT NULL, "fileName" TEXT, "storageKey" TEXT, "content" TEXT, "timeSignature" TEXT NOT NULL DEFAULT '4/4', "defaultBpm" INTEGER NOT NULL, "totalMeasures" INTEGER NOT NULL, "backingTrackUrl" TEXT, "backingTrackOffsetMs" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ExerciseScore_pkey" PRIMARY KEY ("id"));
CREATE TABLE "LoopRegion" ("id" TEXT NOT NULL, "exerciseId" TEXT NOT NULL, "title" TEXT NOT NULL, "startMeasure" INTEGER NOT NULL, "endMeasure" INTEGER NOT NULL, "defaultBpm" INTEGER, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "LoopRegion_pkey" PRIMARY KEY ("id"));
ALTER TABLE "PracticeSession" ADD COLUMN "loopRegionId" TEXT, ADD COLUMN "targetBpm" INTEGER, ADD COLUMN "durationSeconds" INTEGER;
CREATE UNIQUE INDEX "ExerciseScore_exerciseId_key" ON "ExerciseScore"("exerciseId"); CREATE UNIQUE INDEX "LoopRegion_exerciseId_startMeasure_endMeasure_key" ON "LoopRegion"("exerciseId", "startMeasure", "endMeasure"); CREATE INDEX "LoopRegion_exerciseId_startMeasure_idx" ON "LoopRegion"("exerciseId", "startMeasure"); CREATE INDEX "PracticeSession_loopRegionId_idx" ON "PracticeSession"("loopRegionId");
ALTER TABLE "ExerciseScore" ADD CONSTRAINT "ExerciseScore_exerciseId_fkey" FOREIGN KEY ("exerciseId") REFERENCES "Exercise"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "LoopRegion" ADD CONSTRAINT "LoopRegion_exerciseId_fkey" FOREIGN KEY ("exerciseId") REFERENCES "Exercise"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "PracticeSession" ADD CONSTRAINT "PracticeSession_loopRegionId_fkey" FOREIGN KEY ("loopRegionId") REFERENCES "LoopRegion"("id") ON DELETE SET NULL ON UPDATE CASCADE;
